<?php
$branches=rows('SELECT b.*, COUNT(DISTINCT s.id) AS class_count, COUNT(DISTINCT s.teacher_id) AS teacher_count FROM branches b LEFT JOIN schedules s ON s.branch_id=b.id GROUP BY b.id ORDER BY b.branch_name');
?>
<div class="page-heading heading-with-action"><div><div class="eyebrow">DANH MỤC HỆ THỐNG</div><h1>Cơ sở đào tạo <span class="heading-dot">.</span></h1><p>Theo dõi địa điểm tổ chức giảng dạy và quy mô sử dụng từng cơ sở.</p></div><a class="btn btn-primary" href="<?= e(app_url('branch-form')) ?>"><svg><use href="#i-plus"/></svg> Thêm cơ sở</a></div>
<div class="branch-cards"><?php foreach($branches as $branch): ?><article class="branch-card"><div class="branch-top"><span class="branch-icon"><svg><use href="#i-building"/></svg></span><span class="branch-index">CS <?= str_pad((string)$branch['id'],2,'0',STR_PAD_LEFT) ?></span></div><h2><?= e($branch['branch_name']) ?></h2><p class="branch-address"><?= e($branch['address']) ?></p><div class="branch-stats"><span><strong><?= (int)$branch['class_count'] ?></strong><small>Lịch giảng dạy</small></span><span><strong><?= (int)$branch['teacher_count'] ?></strong><small>Giảng viên</small></span></div><div class="branch-actions"><a href="<?= e(app_url('branch-form',['id'=>$branch['id']])) ?>" class="btn btn-ghost btn-sm">Chỉnh sửa</a><form method="post" action="<?= e(app_url('branches')) ?>" data-confirm="Xóa cơ sở <?= e($branch['branch_name']) ?>? Chỉ có thể xóa cơ sở không có lịch."><?= csrf_field() ?><input type="hidden" name="action" value="delete-branch"><input type="hidden" name="id" value="<?= (int)$branch['id'] ?>"><button type="submit" class="action-delete">Xóa cơ sở</button></form></div></article><?php endforeach; ?><?php if(!$branches): ?><div class="empty-card">Chưa có cơ sở. Hãy tạo cơ sở đào tạo đầu tiên.</div><?php endif; ?></div>
